import * as dotenv from 'dotenv';
dotenv.config({ override: true });

import { createHash } from 'crypto';
import { createClient } from '@supabase/supabase-js';

const ELASTIC_SEARCH_URL = 'https://elastic.kulturhusetstadsteatern.se/khst-events';

const supabase = createClient(
  process.env.SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
);

function buildDedupHash(source: string, sourceId: string): string {
  return createHash('sha256').update(`${source}::${sourceId}`).digest('hex');
}

function mapKulturhusetEvent(event: any) {
  const source = event._source;

  // Parse the date correctly - keep the full ISO string with timezone
  let start_time = '';

  if (source.tixStartDate) {
    // Parse the date and convert to UTC ISO string for storage
    const startDate = new Date(source.tixStartDate);
    start_time = startDate.toISOString();
  }

  // Extract venue
  const venues = source.tixVenue || [];
  const venue = venues[0]?.label || 'Kulturhuset Stadsteatern';

  // Extract location/area
  const locations = source.drupalLocation || [];
  const area = locations[0]?.label || 'Stockholm';

  // Extract description
  const descriptions = source.drupalLeadText || [];
  const description = descriptions[0]?.value || '';

  // Extract URL
  const url = source.drupalLink || '';

  // Extract title
  const title = source.drupalTitle || source.tixName || 'Untitled Event';

  // Map category
  const categories = source.drupalCategory || [];
  const categoryLabel = categories[0]?.label?.toLowerCase() || '';
  const category = mapCategory(categoryLabel);

  // Generate unique ID
  const id = `kh-${source.tixEventId || source.drupalId || Math.random().toString(36).substr(2, 9)}`;

  return {
    id,
    title,
    start_time,
    venue,
    area,
    description: description.substring(0, 500),
    url,
    category,
    source: 'kulturhuset',
  };
}

function mapCategory(label: string): string {
  const categoryMap: Record<string, string> = {
    'teater': 'culture',
    'musik': 'music',
    'konsert': 'music',
    'dans': 'culture',
    'film': 'culture',
    'litteratur': 'culture',
    'konst': 'culture',
    'utställning': 'culture',
    'barn & ung': 'barn',
    'barn': 'barn',
    'familj': 'barn',
    'sport': 'sports',
    'mat & dryck': 'food',
    'food': 'food',
    'nattliv': 'nightlife',
    'skapa': 'culture',
    'för skolan': 'barn',
  };
  return categoryMap[label] || 'culture';
}

async function fetchKulturhusetEvents(limit = 20) {
  const query = {
    size: limit,
    query: {
      bool: {
        must: [
          {
            range: {
              tixStartDate: {
                gte: 'now'
              }
            }
          }
        ]
      }
    },
    sort: [
      { tixStartDate: { order: 'asc' } }
    ]
  };

  const response = await fetch(ELASTIC_SEARCH_URL + '/_search', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'User-Agent': 'EventPulse/1.0',
    },
    body: JSON.stringify(query)
  });

  const data = await response.json();
  if (!data.hits?.hits) return [];
  return data.hits.hits.map(mapKulturhusetEvent);
}

async function insertKulturhusetEvents() {
  console.log('Fetching Kulturhuset events with correct timestamps...');
  const events = await fetchKulturhusetEvents({ size: 20 } as any);
  console.log(`Got ${events.length} events`);

  // Show sample dates
  console.log('\nSample events:');
  events.slice(0, 3).forEach(e => console.log(`  ${e.title} - ${e.start_time}`));

  let inserted = 0;
  let updated = 0;
  let errors = 0;

  for (const event of events) {
    const dedupHash = buildDedupHash('kulturhuset', event.id);

    // Check if exists
    const { data: existing } = await supabase
      .from('events')
      .select('id')
      .eq('dedup_hash', dedupHash)
      .single();

    if (existing) {
      // Update existing with correct timestamp
      const { error } = await supabase
        .from('events')
        .update({
          title_en: event.title,
          description_en: event.description,
          start_time: event.start_time,
          source: 'kulturhuset',
          source_id: event.id,
          category_slug: event.category,
          status: 'published',
          updated_at: new Date().toISOString(),
        })
        .eq('id', existing.id);

      if (error) {
        console.error(`Error updating ${event.id}:`, error.message);
        errors++;
      } else {
        updated++;
      }
    } else {
      // Insert new
      const { error } = await supabase
        .from('events')
        .insert({
          title_en: event.title,
          description_en: event.description,
          start_time: event.start_time,
          source: 'kulturhuset',
          source_id: event.id,
          category_slug: event.category,
          status: 'published',
          dedup_hash: dedupHash,
          venue_id: null,
          lat: 59.3293,
          lng: 18.0686,
        });

      if (error) {
        console.error(`Error inserting ${event.id}:`, error.message);
        errors++;
      } else {
        inserted++;
      }
    }
  }

  console.log(`\n✅ Inserted: ${inserted}, Updated: ${updated}, Errors: ${errors}`);
  return { inserted, updated, errors };
}

async function verifyEvents() {
  console.log('\nVerifying events in Supabase...');

  // Check future events
  const now = new Date().toISOString();
  console.log('Current UTC time:', now);

  const { count } = await supabase
    .from('events')
    .select('id', { count: 'exact', head: true })
    .eq('source', 'kulturhuset')
    .eq('status', 'published');

  console.log(`Total Kulturhuset events in DB: ${count}`);

  const { data: events } = await supabase
    .from('events')
    .select('id, title_en, start_time')
    .eq('source', 'kulturhuset')
    .eq('status', 'published')
    .gte('start_time', now)
    .order('start_time', { ascending: true });

  console.log(`\nFuture Kulturhuset events (gte now): ${events?.length || 0}`);
  events?.forEach(e => console.log(`  ${e.start_time} - ${e.title_en?.substring(0, 40)}`));
}

async function main() {
  try {
    await insertKulturhusetEvents();
    await verifyEvents();
  } catch (error) {
    console.error('Fatal error:', (error as Error).message);
  }
}

main();
